function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 25) return 's needs 1 to 25 characters.';
  if (!/^[a-z()]+$/.test(s)) return 's may contain only lowercase letters and parentheses.';
  if (s.replace(/[a-z]/g, '').length > 20) return 's may contain at most 20 parentheses.';
  return null;
}

