function removeInvalidParentheses(s) {
  let extraOpen = 0;
  let extraClose = 0;
  for (const ch of s) {
    if (ch === '(') {
      extraOpen++;
    } else if (ch === ')') {
      if (extraOpen > 0) {
        extraOpen--;
      } else {
        extraClose++;
      }
    }
  }
  const results = new Set();
  const kept = [];

  function backtrack(index, balance, openLeft, closeLeft) {
    if (index === s.length) {
      if (balance === 0 && openLeft === 0 && closeLeft === 0) {
        results.add(kept.join(''));
      }
      return;
    }
    const ch = s[index];
    if (ch === '(' && openLeft > 0) {
      backtrack(index + 1, balance, openLeft - 1, closeLeft);
    }
    if (ch === ')' && closeLeft > 0) {
      backtrack(index + 1, balance, openLeft, closeLeft - 1);
    }
    kept.push(ch);
    if (ch === '(') {
      backtrack(index + 1, balance + 1, openLeft, closeLeft);
    } else if (ch !== ')') {
      backtrack(index + 1, balance, openLeft, closeLeft);
    } else if (balance > 0) {
      backtrack(index + 1, balance - 1, openLeft, closeLeft);
    }
    kept.pop();
  }

  backtrack(0, 0, extraOpen, extraClose);
  return [...results];
}

