function removeInvalidParentheses(s) {
  // Breadth-first search over deletions: the first level holding a balanced string is the minimum.
  const balanced = text => {
    let depth = 0;
    for (const c of text) {
      if (c === '(') depth++;
      else if (c === ')' && --depth < 0) return false;
    }
    return depth === 0;
  };
  let level = new Set([s]);
  for (;;) {
    const good = [...level].filter(balanced);
    if (good.length) return good;
    const next = new Set();
    for (const text of level)
      for (let i = 0; i < text.length; i++)
        if (text[i] === '(' || text[i] === ')') next.add(text.slice(0, i) + text.slice(i + 1));
    level = next;
  }
}

