function generate(rand, size) {
  const letters = 'abc';
  const pick = m => Math.floor(rand() * m);
  if (size === 'large') {
    const chars = [];
    for (let i = 0; i < 20; i++) chars.push(rand() < 0.5 ? '(' : ')');
    for (let i = 0; i < 5; i++) chars.splice(pick(chars.length + 1), 0, letters[pick(3)]);
    return [chars.join('')];
  }
  const length = 1 + pick(10);
  const letterRate = rand() < 0.3 ? 0 : rand() * 0.4;
  const openRate = 0.3 + rand() * 0.4;
  let s = '';
  for (let i = 0; i < length; i++) {
    if (rand() < letterRate) s += letters[pick(3)];
    else s += rand() < openRate ? '(' : ')';
  }
  return [s];
}
